import{_ as e,o as t,a as i,b as p}from"./app.C41L12d5.js";const o="/ascendc.github.io/assets/matrix_computation_workflow.BgN-mxOU.png",_="/ascendc.github.io/assets/mx_matrix_computation_workflow.w8ZI7U6O.png",r="/ascendc.github.io/assets/sparse_matrix_computation_workflow.DX7mASta.png",f="/ascendc.github.io/assets/conv2d_forward.3VCFLLRl.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"概述","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/overview/overview"},{"text":"矩阵计算流程","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_flow"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_flow.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_flow.md","lastUpdated":1785832713000}'),u={name:"api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_flow.md"};function c(l,a,m,s,d,n){return t(),i("div",null,[...a[0]||(a[0]=[p('<div><article class="markdown-body"><h1>普通矩阵计算流程<span id="ZH-CN_TOPIC_0000002568950891"></span></h1><p>Ascend C针对矩阵计算编程模型提供了四类接口，分别承载Cube核中各个通路的搬运能力和计算能力，如下图所示：</p><p><strong>图1</strong> 普通矩阵基础计算流程图<span id="zh-cn_topic_0000002535567224_fig135639216485"></span><br><img src="'+o+'" alt title="普通矩阵基础计算流程图"></p><ol><li><p>通过DataCopy接口将A、B原始矩阵的GM数据搬运到L1 Buffer中（如果存在Bias/随路量化，则同样通过DataCopy搬运到L1 Buffer中）。详细内容请参考<a href="../cube_compute_load/cube_compute_load.html">矩阵数据搬入至L1 Buffer</a>。</p></li><li><p>通过LoadData接口将A、B矩阵分别加载到L0A Buffer和L0B Buffer上准备计算（如果存在Bias/随路量化，则通过DataCopy将L1 Buffer中的bias数据/量化系数数据搬运到BT Buffer/Fixpipe Buffer上）。详细内容请参考<a href="../cube_compute_load/cube_compute_load.html">矩阵数据搬入至L0A Buffer/L0B Buffer</a>。</p></li><li><p>通过Mmad接口对L0A Buffer、L0B Buffer、BT Buffer上面的数据进行矩阵计算，并输出结果到L0C Buffer上。详细内容请参考<a href="../mmad_compute/Mmad.html">Mmad计算</a>。</p></li><li><p>通过Fixpipe接口将L0C Buffer的数据进行处理并搬出到GM，Fixpipe接口可以利用Fixpipe Buffer数据进行如随路量化、Relu等操作。详细内容请参考<a href="../cube_compute_store/Fixpipe_L0CToGM.html">Fixpipe（L0C到GM数据搬运）</a>。</p></li></ol><div data-filter="950"><h1>Mx矩阵计算流程<span id="ZH-CN_TOPIC_0000002568950892"></span></h1><p>Mx矩阵计算仅在Ascend 950PR/Ascend 950DT型号支持。</p><p>MxMmad（全称Microscaling Mmad）为带有量化系数的矩阵乘法，即左矩阵和右矩阵均有对应的量化系数矩阵，左量化系数矩阵scaleA和右量化系数矩阵scaleB。MxMmad场景中，左量化系数矩阵与左矩阵乘积，右量化系数矩阵与右矩阵乘积，对两个乘积的结果做矩阵乘法。Ascend C针对Mx矩阵计算编程模型提供了对应Mx类接口，如下图所示：</p><p><strong>图 2</strong> Mx矩阵基础计算流程图<span id="zh-cn_topic_0000002535567225_fig135639216486"></span><br><img src="'+_+'" alt title="Mx矩阵基础计算流程图"></p><ol><li><p>通过DataCopy接口将A、B原始矩阵、<a href="../cube_compute_fractal_intro/aux_cube_fractal_format_details.html#section_mx_scalea_fractal_format">左系数矩阵scaleA</a>、<a href="../cube_compute_fractal_intro/aux_cube_fractal_format_details.html#section_mx_scaleb_fractal_format">右系数矩阵scaleB</a>的GM数据搬运到L1 Buffer中（如果存在Bias/随路量化，则同样通过DataCopy搬运到L1 Buffer中）。详细内容请参考<a href="../cube_compute_load/cube_compute_load.html">矩阵数据搬入至L1 Buffer</a>。</p></li><li><p>通过<a href="../cube_compute_load/LoadData_2D_MX.html">LoadData（MX矩阵搬运）接口</a>将A矩阵与scaleA矩阵加载到L0A Buffer与内置L0A_MX Buffer、将B矩阵与scaleB矩阵分别加载到L0B Buffer与L0B_MX Buffer上准备计算（如果存在Bias/随路量化，则通过DataCopy将L1 Buffer中的bias数据/量化系数数据搬运到BT Buffer/Fixpipe Buffer上）。详细内容请参考<a href="../cube_compute_load/cube_compute_load.html">矩阵数据搬入至L0A Buffer/L0B Buffer</a>。</p></li><li><p>通过MmadMx接口对L0A Buffer、L0A_MX Buffer、L0B Buffer、L0B_MX Buffer、BT Buffer上面的数据进行矩阵计算，并输出结果到L0C Buffer上。详细内容请参考<a href="../mmad_compute/MmadMx.html">MmadMx计算</a>。</p></li><li><p>通过Fixpipe接口将L0C Buffer的数据进行处理并搬出到GM，Fixpipe接口可以利用Fixpipe Buffer数据进行如随路量化、Relu等操作。详细内容请参考<a href="../cube_compute_store/Fixpipe_L0CToGM.html">Fixpipe（L0C到GM数据搬运）</a>。</p></li></ol></div><div data-filter="910b,A3"><h1>4选2稀疏矩阵计算流程<span id="ZH-CN_TOPIC_0000002538231116"></span></h1><p>稀疏矩阵是一种特殊类型的矩阵，即矩阵中包含较多的零元素。4选2结构化稀疏矩阵计算，要求一个连续的4个权重或激活值的组（通常是张量中的一行或一列）中，最多只有2个值为非零，其余2个强制为零。针对Atlas A2训练系列产品/Atlas A2推理系列产品和Atlas A3训练系列产品/Atlas A3推理系列产品，Ascend C针对4选2稀疏矩阵计算编程模型提供了对应sparse类接口，如下图所示：</p><p><strong>图 3</strong> 4选2稀疏矩阵基础计算流程图<span id="zh-cn_topic_0000002566526987_fig12280145134813"></span><br><img src="'+r+'" alt title="4选2稀疏矩阵基础计算流程图"></p><ol><li><p>首先将原始矩阵B按照固定粒度划分连续4个元素为一组，按照固定结构稠密算法，离线生成对应的稠密矩阵B与<a href="../cube_compute_fractal_intro/aux_cube_fractal_format_details.html#zh-cn_topic_0000002563445163_section1873692415233">索引矩阵</a>作为输入。</p></li><li><p>通过DataCopy接口将原始矩阵A（稀疏矩阵）、稠密矩阵B、索引矩阵的GM数据搬运到L1 Buffer中（如果存在随路量化，则同样通过DataCopy搬运到L1 Buffer中）。详细内容请参考<a href="../cube_compute_load/cube_compute_load.html">矩阵数据搬入至L1 Buffer</a>。</p></li><li><p>通过LoadData接口将原始矩阵A加载到L0A Buffer，通过<a href="../cube_compute_load/LoadDataWithSparse.html">LoadDataWithSparse接口</a>将稠密矩阵B与索引矩阵分别加载到L0B Buffer与内置IDX Buffer上准备计算（如果存在随路量化，则通过DataCopy将L1 Buffer中的量化系数数据搬运到Fixpipe Buffer上）。详细内容请参考<a href="../cube_compute_load/cube_compute_load.html">矩阵数据搬入至L0A Buffer/L0B Buffer</a>。</p></li><li><p>通过MmadWithSparse接口对L0A Buffer、L0B Buffer、内置IDX Buffer上面的数据进行4选2稀疏矩阵计算，并输出结果到L0C Buffer上。详细内容请参考<a href="../mmad_compute/MmadWithSparse.html">MmadWithSparse计算</a>。</p></li><li><p>通过Fixpipe接口将L0C Buffer的数据进行处理并搬出到GM，Fixpipe接口可以利用Fixpipe Buffer数据进行如随路量化、Relu等操作。详细内容请参考<a href="../cube_compute_store/Fixpipe_L0CToGM.html">Fixpipe（L0C到GM数据搬运）</a>。</p></li></ol></div><h1>Conv2D前向计算流程<span id="ZH-CN_TOPIC_0000002568950893"></span></h1><p>Conv2D前向计算的本质是将卷积运算转换为矩阵乘：先通过img2col（Image to Column）将FeatureMap按卷积核滑动窗口展开为左矩阵A，将Weight作为右矩阵B，再做矩阵乘累加得到输出。与<a href="#ZH-CN_TOPIC_0000002568950891">普通矩阵计算流程</a>的区别在于：A矩阵从GM直接搬入后，由<a href="../cube_compute_load/LoadData_3D.html">LoadData（卷积数据搬运）</a>在L1 Buffer到L0A Buffer的搬运过程中，根据卷积核尺寸、stride、dilation、padding在线完成img2col空间展开生成，如下图所示：</p><p><strong>图 4</strong> Conv2D前向计算流程图<span id="zh-cn_topic_0000002568950893_fig135639216487"></span><br><img src="'+f+'" alt title="Conv2D前向计算流程图"></p><ol><li><p>通过DataCopy接口将FeatureMap、Weight的GM数据搬运到L1 Buffer中。FeatureMap搬运时完成到<a href="../cube_compute_fractal_intro/key_fractal_format_details.html#zh-cn_topic_0000002545089965_section217615301084">NC1HWC0格式</a>的随路转换；Weight搬运到L1 Buffer得到Nz分形布局。详细内容请参考<a href="../cube_compute_load/cube_compute_load.html">矩阵计算的搬入</a>。</p></li><li><p>通过<a href="../cube_compute_load/LoadData_3D.html">LoadData（卷积数据搬运）</a>接口将L1 Buffer中的FeatureMap执行img2col，根据卷积核尺寸、stride、dilation、padding完成空间展开与padding填充，生成L0A Buffer上的左矩阵A；通过LoadData接口将L1 Buffer中的Weight搬运到L0B Buffer得到右矩阵B。FeatureMap的属性描述（l1H、l1W、padList）可通过<a href="../cube_compute_load/LoadData_3D.html#zh-cn_topic_0000002512171652_table679014222918">LoadData3DParamsV1</a>/<a href="../cube_compute_load/LoadData_3D.html#zh-cn_topic_0000002512171652_table193501032193419">LoadData3DParamsV2</a>/<a href="../cube_compute_load/LoadData_3D.html#zh-cn_topic_0000002512171652_table118027314415">LoadData3DParamsV2Pro</a>结构体字段设置，也可在LoadData接口defaultConfig参数的isSetFMatrix字段为false时通过<a href="../cube_load_aux_config/SetFmatrix.html">SetFmatrix</a>显式设置（fmatrixMode需与结构体的fMatrixCtrl保持一致）；img2col的repeat参数需通过<a href="../cube_load_aux_config/SetLoadDataRepeat.html">SetLoadDataRepeat</a>配置，padding填充值可通过结构体字段或<a href="../cube_load_aux_config/SetLoadDataPaddingValue.html">SetLoadDataPaddingValue</a>设置。详细内容请参考<a href="../cube_compute_load/cube_compute_load.html">矩阵计算的搬入</a>。</p></li><li><p>通过Mmad接口对L0A Buffer、L0B Buffer上的数据进行矩阵计算，并输出结果到L0C Buffer上。详细内容请参考<a href="../mmad_compute/Mmad.html">Mmad计算</a>。</p></li><li><p>通过Fixpipe接口将L0C Buffer的数据进行处理并按指定格式搬出到GM，Fixpipe接口可以利用Fixpipe Buffer数据进行如随路量化、Relu等操作。L0C Buffer上存放的卷积结果为NC1HWC0格式，Fixpipe通过<a href="../cube_store_key_features/NZ2ND.html">NZ2ND</a>能力将其转为NHWC格式输出。<span data-filter="950">特别地，针对Ascend 950PR/Ascend 950DT产品，Fixpipe还支持通过<a href="../cube_store_key_features/NZ2DN.html">NZ2DN</a>能力将L0C Buffer上的卷积结果转为NCHW格式输出。</span>详细内容请参考<a href="../cube_store_key_features/convolution_format_conversion.html">卷积格式转换</a>。更多搬出相关内容请参考<a href="../cube_compute_store/cube_compute_store.html">矩阵计算的搬出</a>。</p></li></ol></article></div>',1)])])}const L=e(u,[["render",c]]);export{h as __pageData,L as default};
